<?php require_once __DIR__.'/../includes/functions.php';$u=require_login();$id=(int)$u['id'];$q=db()->prepare('SELECT r.*,a.name sender,b.name receiver FROM study_requests r JOIN users a ON a.id=r.sender_id JOIN users b ON b.id=r.receiver_id WHERE r.sender_id=? OR r.receiver_id=? ORDER BY r.created_at DESC');$q->execute([$id,$id]);page_start('Study requests'); ?><div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Student</th><th>Direction</th><th>Status</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($q as $r):$incoming=(int)$r['receiver_id']===$id; ?><tr><td class="fw-semibold"><?= e($incoming?$r['sender']:$r['receiver']) ?></td><td><?= $incoming?'Received':'Sent' ?></td><td><span class="status"><?= e($r['status']) ?></span></td><td><?= e($r['created_at']) ?></td><td><?php if($incoming&&$r['status']==='pending'):foreach(['accept'=>'Accept','reject'=>'Reject'] as $action=>$label): ?><form class="d-inline" method="post" action="../actions/partner-request.php"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= $r['id'] ?>"><input type="hidden" name="intent" value="<?= $action ?>"><button class="btn btn-sm <?= $action==='accept'?'btn-primary':'btn-outline-secondary' ?>"><?= $label ?></button></form> <?php endforeach;elseif(!$incoming&&$r['status']==='pending'): ?><form method="post" action="../actions/partner-request.php"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="request_id" value="<?= $r['id'] ?>"><input type="hidden" name="intent" value="cancel"><button class="btn btn-sm btn-outline-secondary">Cancel</button></form><?php elseif($r['status']==='accepted'): ?><a class="btn btn-sm btn-outline-primary" href="messages.php?user=<?= $incoming?(int)$r['sender_id']:(int)$r['receiver_id'] ?>">Message</a><?php endif ?></td></tr><?php endforeach ?></tbody></table></div></div><?php page_end(); ?>
